import {test} from 'node:test';import assert from 'node:assert/strict';
import {population} from '../town-life/people/core.mjs';
import {createGenerations,advanceGenerations,canMarry,routine} from '../ranch-generations.mjs';
test('marriage is adult human and gender independent',()=>{const s=createGenerations(42,population(42,'alder').slice(0,2),1);const [a,b]=s.people;for(const gender of ['woman','man','nonbinary']){a.gender=b.gender=gender;assert.ok(canMarry(a,b,0));}b.born=-17;assert.equal(canMarry(a,b,0),false);b.born=-25;b.species='goat';assert.equal(canMarry(a,b,0),false);});
test('generations inherit appearance, retire and die; deterministic after restore',()=>{const s=createGenerations(42,population(42,'alder').slice(0,4),2);advanceGenerations(s,801);const saved=structuredClone(s);advanceGenerations(s,2001);advanceGenerations(saved,2001);assert.deepEqual(s,saved);assert.ok(s.people.some(p=>!p.alive));assert.ok(s.people.some(p=>p.generation>1));for(const p of s.people.filter(p=>p.parents.length)){const parents=p.parents.map(id=>s.people.find(q=>q.id===id));assert.ok(parents.some(q=>q.appearance.skin===p.appearance.skin));}assert.equal(routine({alive:true,age:10},10),'At school off-ranch');assert.equal(routine({alive:true,age:70},10),'Retired · at home');});
import {farmhandsNeeded} from '../ranch-generations.mjs';
test('farmhands cover adult daytime shortages without child or retired labor',()=>{const people=[{alive:true,age:12},{alive:true,age:72},{alive:true,age:30,occupation:'town'}];assert.equal(farmhandsNeeded(people,11,18),3);assert.equal(farmhandsNeeded(people,23,18),0);people.push({alive:true,age:30,occupation:'ranch'});assert.equal(farmhandsNeeded(people,11,18),2);});
test('changing calendar pace does not rewind or jump age',()=>{const s=createGenerations(3,population(3,'alder').slice(0,2),1);advanceGenerations(s,100,{year:2});const ages=s.people.map(p=>p.age);advanceGenerations(s,101,{year:2.1,daysPerYear:.25});assert.deepEqual(s.people.map(p=>p.age),ages);});
test('parents are adults when family members arrive and existing spouses are respected',()=>{const s=createGenerations(31,population(31,'alder').slice(0,6),3);advanceGenerations(s,1601);for(const child of s.people.filter(p=>p.parents.length))for(const id of child.parents){const parent=s.people.find(p=>p.id===id);assert.ok(child.born-parent.born>=18);}const [a,b]=s.people;a.alive=b.alive=true;a.spouse='someone';assert.equal(canMarry(a,b,s.year),false);});
